  for (const c of [notes, withheld, escalation({ pendingCount: 0, meaningfulChange: true, checksPass: false })]) {
    assert.equal(typeof c.detail, 'string');
    assert.ok(c.detail.length > 0 && c.detail.length < 160, c.detail);
  }
});

